<?php declare(strict_types=1);require_once __DIR__.'/../shared/response.php';require_once __DIR__.'/../shared/request.php';methodOnly('POST');safeApi(function():void{$i=jsonRequest();$email=strtolower(inputString($i,'email',true));$otp=inputString($i,'otp',true);$db=apiDatabase();$q=$db->prepare('SELECT * FROM customer_pending_registrations WHERE email=:email AND expires_at>NOW()');$q->execute([':email'=>$email]);$pending=$q->fetch();$q=$db->prepare("SELECT * FROM customer_email_otps WHERE email=:email AND purpose='SIGNUP' AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1");$q->execute([':email'=>$email]);$record=$q->fetch();if(!$pending||!$record||!password_verify($otp,$record['otp_hash']))jsonResponse(false,'Invalid or expired verification code.',null,[],422);$db->beginTransaction();$q=$db->prepare('INSERT INTO customers(name,email,phone,password_hash,email_verified_at,status) VALUES(:name,:email,:phone,:hash,NOW(),"ACTIVE")');$q->execute([':name'=>$pending['name'],':email'=>$pending['email'],':phone'=>$pending['phone'],':hash'=>$pending['password_hash']]);$db->prepare('UPDATE customer_email_otps SET used_at=NOW() WHERE id=:id')->execute([':id'=>$record['id']]);$db->prepare('DELETE FROM customer_pending_registrations WHERE id=:id')->execute([':id'=>$pending['id']]);$db->commit();jsonResponse(true,'Account verified successfully.');});
